import{_ as t,c as o,o as a,al as i}from"./chunks/framework.CT7RwC5a.js";const _=JSON.parse('{"title":"Test MC_06 - Optical Flow","description":"","frontmatter":{},"headers":[],"relativePath":"ko/test_cards/mc_06_optical_flow.md","filePath":"ko/test_cards/mc_06_optical_flow.md"}'),l={name:"ko/test_cards/mc_06_optical_flow.md"};function r(n,e,s,c,h,d){return a(),o("div",null,e[0]||(e[0]=[i('<h1 id="test-mc-06-optical-flow" tabindex="-1">Test MC_06 - Optical Flow <a class="header-anchor" href="#test-mc-06-optical-flow" aria-label="Permalink to &quot;Test MC_06 - Optical Flow&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>To test that optical flow works as expected</p><h2 id="preflight" tabindex="-1">Preflight <a class="header-anchor" href="#preflight" aria-label="Permalink to &quot;Preflight&quot;">​</a></h2><p>Disconnect all GPS / compasses and ensure vehicle is using optical flow for navigation (<a href="./../sensor/optical_flow.html">Setup Information here</a>)</p><p>Ensure there are no other sources of positioning besides optical flow</p><ul><li><a href="./../advanced_config/parameter_reference.html#EKF2_OF_CTRL">EKF2_OF_CTRL</a>: <code>1</code></li><li><a href="./../advanced_config/parameter_reference.html#EKF2_GPS_CTRL">EKF2_GPS_CTRL</a>: <code>0</code></li><li><a href="./../advanced_config/parameter_reference.html#EKF2_EV_CTRL">EKF2_EV_CTRL</a>: <code>0</code></li><li><a href="./../advanced_config/parameter_reference.html#SYS_HAS_MAG">SYS_HAS_MAG</a>: <code>0</code></li></ul><p>Ensure that the drone can go into Altitude / Position flight mode while still on the ground</p><h2 id="flight-tests" tabindex="-1">Flight Tests <a class="header-anchor" href="#flight-tests" aria-label="Permalink to &quot;Flight Tests&quot;">​</a></h2><p>❏ Altitude flight mode</p><p>    ❏ Vertical position should hold current value with stick centered</p><p>    ❏ Pitch/Roll/Yaw response 1:1</p><p>    ❏ Throttle response set to climb/descent rate</p><p>❏ Position flight mode</p><p>    ❏ Horizontal position should hold current value with stick centered</p><p>    ❏ Vertical position should hold current value with stick centered</p><p>    ❏ Throttle response set to climb/descent rate</p><p>    ❏ Pitch/Roll/Yaw response set to pitch/roll/yaw rates</p><h2 id="착륙" tabindex="-1">착륙 <a class="header-anchor" href="#착륙" aria-label="Permalink to &quot;착륙&quot;">​</a></h2><p>❏ Land in either Position or Altitude mode with the throttle below 40%</p><p>❏ Upon touching ground, copter should disarm automatically within 2 seconds (default: see <a href="./../advanced_config/parameter_reference.html#COM_DISARM_LAND">COM_DISARM_LAND</a>)</p><h2 id="예상-결과" tabindex="-1">예상 결과 <a class="header-anchor" href="#예상-결과" aria-label="Permalink to &quot;예상 결과&quot;">​</a></h2><ul><li>추력을 올릴 때 서서히 이륙한다</li><li>Drone should hold altitude in Altitude Flight mode without wandering</li><li>Drone should hold position within 1 meter in Position Flight mode without pilot moving sticks</li><li>위에 언급한 어떤 비행 모드에서도 떨림이 나타나서는 안됨</li><li>지면에 착륙시, 콥터가 지면에서 튀면 안됨</li></ul>',23)]))}const f=t(l,[["render",r]]);export{_ as __pageData,f as default};
